            "/events/{id}/candidates/{candidate_id}".replace("{" + "id" + "}", "$id").replace("{" + "candidate_id" + "}", "$candidateId"),
            query = localVariableQuery,
            headers = localVariableHeaders,
            requiresAuthentication = true,
            )

            return request(
            localVariableConfig,
            localVariableBody,
            localVariableAuthNames
            ).wrap()
            }

        }
